// Faithful browser simulation: a real browser fires focusout on the blurred input
// DURING removeChild, before the node detaches, so isConnected is still true and the
// 'editing' class is still present. Patch removeChild to fire that focusout first.
const todoList = d.querySelector('.todo-list');
const origRemove = todoList.removeChild.bind(todoList);
todoList.removeChild = function(node) {
  const edit = node.querySelector ? node.querySelector('.edit') : null;
  if (edit) {
    const fout = new w.Event('focusout', { bubbles: true });
    edit.dispatchEvent(fout);
  }
  return origRemove(node);
};

